const listSchedules = `-- name: ListSchedules :many
SELECT id, tenant_id, schedule_no, contract_id, contract_no, customer_id, customer_name, carrier_forwarder, vessel_name, voyage_no, port_of_loading, port_of_discharge, etd, atd, eta, ata, responsible_employee_id, responsible_name, status, remark, created_by, created_by_name, created_at, updated_by, updated_by_name, updated_at, original_eta, eta_revision, route_version, delay_days, has_temporary_call, current_progress, latest_progress_at, current_route_node_id, carrier_id, loading_port_id, loading_port_code, loading_port_timezone, discharge_port_id, discharge_port_code, discharge_port_timezone, count(*) OVER () AS total
FROM shipping_schedules
WHERE tenant_id = $1
  AND (
    $2::text = ''
    OR schedule_no ILIKE '%' || $2::text || '%'
    OR contract_no ILIKE '%' || $2::text || '%'
    OR customer_name ILIKE '%' || $2::text || '%'
    OR vessel_name ILIKE '%' || $2::text || '%'
    OR voyage_no ILIKE '%' || $2::text || '%'
    OR responsible_name ILIKE '%' || $2::text || '%'
  )
  AND (
    $3::text = ''
    OR ($3::text = 'ACTIVE' AND status NOT IN ('COMPLETED','CANCELLED'))
    OR ($3::text = 'ARCHIVED' AND status IN ('COMPLETED','CANCELLED'))
    OR status = $3::text
  )
  AND ($4::text = '' OR port_of_loading = $4::text)
  AND ($5::text = '' OR port_of_discharge = $5::text)
  AND ($6::date IS NULL OR etd >= $6::date)
  AND ($7::date IS NULL OR etd <= $7::date)
  AND ($8::date IS NULL OR eta >= $8::date)
  AND ($9::date IS NULL OR eta <= $9::date)
ORDER BY
  CASE WHEN eta >= CURRENT_DATE THEN 0 ELSE 1 END,
  CASE WHEN eta >= CURRENT_DATE THEN eta END ASC,
  updated_at DESC
LIMIT $11 OFFSET $10
`

